import type { SupabaseClient } from "@supabase/supabase-js"

import type {
  Booking,
  Category,
  ClientLogo,
  ContentPort,
  Experience,
  Faq,
  MediaAsset,
  MediaPort,
  Photo,
  Plan,
  Project,
  SettingsPort,
  Testimonial,
} from "@/registry/retana/lib/admin-types"

/**
 * Host-owned Supabase client. This module never constructs one.
 * Column names match registry/lib/supabase/001_admin_content.sql.
 */

type Row = Record<string, unknown>

export type AdminSupabase = SupabaseClient

function asRows(data: unknown): Row[] {
  if (!Array.isArray(data)) return []
  return data.filter((row): row is Row => typeof row === "object" && row !== null)
}

function asRow(data: unknown): Row {
  if (typeof data === "object" && data !== null && !Array.isArray(data)) return data as Row
  throw new Error("Expected a row")
}

function str(row: Row, key: string): string {
  const value = row[key]
  return typeof value === "string" ? value : value == null ? "" : String(value)
}

function num(row: Row, key: string): number {
  const value = row[key]
  return typeof value === "number" ? value : Number(value ?? 0) || 0
}

function bool(row: Row, key: string): boolean {
  const value = row[key]
  return value === true || value === 1 || value === "true"
}

function nullableNum(row: Row, key: string): number | null {
  const value = row[key]
  if (value == null || value === "") return null
  const parsed = typeof value === "number" ? value : Number(value)
  return Number.isFinite(parsed) ? parsed : null
}

async function throwIf(error: { message: string } | null) {
  if (error) throw new Error(error.message)
}

function contentPort<T extends { id: string; position: number }>(
  client: AdminSupabase,
  table: string,
  fromRow: (row: Row) => T,
  toRow: (row: T) => Row,
): ContentPort<T> {
  return {
    async list() {
      const { data, error } = await client.from(table).select("*").order("position", { ascending: true })
      await throwIf(error)
      return asRows(data).map(fromRow)
    },
    async save(row) {
      const { data, error } = await client.from(table).upsert(toRow(row)).select("*").single()
      await throwIf(error)
      return fromRow(asRow(data))
    },
    async remove(id) {
      const { error } = await client.from(table).delete().eq("id", id)
      await throwIf(error)
    },
    async reorder(ids) {
      const results = await Promise.all(
        ids.map((id, position) => client.from(table).update({ position }).eq("id", id)),
      )
      for (const result of results) await throwIf(result.error)
    },
  }
}

function categoryFrom(row: Row): Category {
  return {
    id: str(row, "id"),
    title: str(row, "title"),
    slug: str(row, "slug"),
    position: num(row, "position"),
    published: bool(row, "published"),
  }
}

function projectFrom(row: Row): Project {
  return {
    id: str(row, "id"),
    title: str(row, "title"),
    slug: str(row, "slug"),
    categoryId: str(row, "category_id") || null,
    summary: str(row, "summary"),
    client: str(row, "client"),
    year: str(row, "year"),
    liveUrl: str(row, "live_url"),
    coverUrl: str(row, "cover_url") || null,
    showOnHomepage: bool(row, "show_on_homepage"),
    published: bool(row, "published"),
    position: num(row, "position"),
  }
}

function projectTo(row: Project): Row {
  return {
    id: row.id,
    title: row.title,
    slug: row.slug,
    category_id: row.categoryId,
    summary: row.summary,
    client: row.client,
    year: row.year,
    live_url: row.liveUrl,
    cover_url: row.coverUrl,
    show_on_homepage: row.showOnHomepage,
    published: row.published,
    position: row.position,
  }
}

export function createSupabaseSettings(client: AdminSupabase): SettingsPort {
  return {
    async getAll() {
      const { data, error } = await client.from("settings").select("key,value")
      await throwIf(error)
      const values: Record<string, string> = {}
      for (const row of asRows(data)) values[str(row, "key")] = str(row, "value")
      return values
    },
    async save(values) {
      const payload = Object.entries(values).map(([key, value]) => ({
        key,
        value,
        updated_at: new Date().toISOString(),
      }))
      const { error } = await client.from("settings").upsert(payload)
      await throwIf(error)
    },
  }
}

export function createSupabaseMedia(client: AdminSupabase, bucket = "media"): MediaPort {
  return {
    async list() {
      const { data, error } = await client.from("media").select("*").order("created_at", { ascending: false })
      await throwIf(error)
      return asRows(data).map(mediaFrom)
    },
    async upload(file) {
      const id = crypto.randomUUID()
      const path = `${id}-${file.name}`
      const uploaded = await client.storage.from(bucket).upload(path, file, {
        contentType: file.type || "application/octet-stream",
        upsert: false,
      })
      await throwIf(uploaded.error)
      const url = client.storage.from(bucket).getPublicUrl(path).data.publicUrl
      const row = {
        id,
        filename: file.name,
        mime: file.type || "application/octet-stream",
        size: file.size,
        url,
        storage_path: path,
        created_at: new Date().toISOString(),
      }
      const inserted = await client.from("media").insert(row).select("*").single()
      await throwIf(inserted.error)
      return mediaFrom(asRow(inserted.data))
    },
    async remove(id) {
      const { data, error } = await client.from("media").select("storage_path").eq("id", id).maybeSingle()
      await throwIf(error)
      const path = data ? str(asRow(data), "storage_path") : ""
      if (path) await throwIf((await client.storage.from(bucket).remove([path])).error)
      await throwIf((await client.from("media").delete().eq("id", id)).error)
    },
  }
}

function mediaFrom(row: Row): MediaAsset {
  return {
    id: str(row, "id"),
    filename: str(row, "filename"),
    mime: str(row, "mime"),
    size: num(row, "size"),
    url: str(row, "url"),
    width: nullableNum(row, "width"),
    height: nullableNum(row, "height"),
    createdAt: str(row, "created_at"),
  }
}

function bookingFrom(row: Row): Booking {
  return {
    id: str(row, "id"),
    name: str(row, "name"),
    email: str(row, "email"),
    phone: str(row, "phone"),
    needs: str(row, "needs"),
    plan: str(row, "plan"),
    note: str(row, "note"),
    source: str(row, "source"),
    cameFrom: str(row, "came_from"),
    status: str(row, "status") === "cancelled" ? "cancelled" : "booked",
    startTime: nullableNum(row, "start_time"),
    endTime: nullableNum(row, "end_time"),
    timezone: str(row, "timezone"),
    meetUrl: str(row, "meet_url"),
    createdAt: num(row, "created_at"),
  }
}

function planFrom(row: Row): Plan {
  return {
    id: str(row, "id"),
    name: str(row, "name"),
    blurb: str(row, "blurb"),
    monthlyPrice: nullableNum(row, "monthly_price"),
    badge: str(row, "badge"),
    ctaLabel: str(row, "cta_label"),
    ctaHref: str(row, "cta_href"),
    features: [],
    position: num(row, "position"),
    published: bool(row, "published"),
  }
}

async function loadPlanFeatures(client: AdminSupabase, plans: Plan[]): Promise<Plan[]> {
  const { data, error } = await client.from("plan_features").select("*").order("position", { ascending: true })
  await throwIf(error)
  const grouped = new Map<string, string[]>()
  for (const row of asRows(data)) {
    const planId = str(row, "plan_id")
    const list = grouped.get(planId) ?? []
    list.push(str(row, "text"))
    grouped.set(planId, list)
  }
  return plans.map((plan) => ({ ...plan, features: grouped.get(plan.id) ?? plan.features }))
}

async function replacePlanFeatures(client: AdminSupabase, planId: string, features: readonly string[]) {
  await throwIf((await client.from("plan_features").delete().eq("plan_id", planId)).error)
  if (features.length === 0) return
  const payload = features.map((text, position) => ({
    id: `${planId}:${position}`,
    plan_id: planId,
    text,
    position,
  }))
  await throwIf((await client.from("plan_features").insert(payload)).error)
}

function plansPort(client: AdminSupabase): ContentPort<Plan> {
  const base = contentPort<Plan>(
    client,
    "plans",
    planFrom,
    (row) => ({
      id: row.id,
      name: row.name,
      blurb: row.blurb,
      monthly_price: row.monthlyPrice,
      badge: row.badge,
      cta_label: row.ctaLabel,
      cta_href: row.ctaHref,
      position: row.position,
      published: row.published,
    }),
  )
  return {
    async list() {
      return loadPlanFeatures(client, await base.list())
    },
    async save(row) {
      const saved = await base.save(row)
      await replacePlanFeatures(client, saved.id, row.features)
      return { ...saved, features: [...row.features] }
    },
    remove: (id) => base.remove(id),
    reorder: (ids) => base.reorder(ids),
  }
}

export function createSupabaseAdmin(client: AdminSupabase, bucket = "media") {
  return {
    settings: createSupabaseSettings(client),
    categories: contentPort(client, "categories", categoryFrom, (row) => ({
      id: row.id,
      title: row.title,
      slug: row.slug,
      position: row.position,
      published: row.published,
    })),
    projects: contentPort(client, "projects", projectFrom, projectTo),
    clients: contentPort<ClientLogo>(client, "clients", (row) => ({
      id: str(row, "id"),
      name: str(row, "name"),
      logoUrl: str(row, "logo_url") || null,
      rowIndex: num(row, "row_index"),
      position: num(row, "position"),
      published: bool(row, "published"),
    }), (row) => ({
      id: row.id,
      name: row.name,
      logo_url: row.logoUrl,
      row_index: row.rowIndex,
      position: row.position,
      published: row.published,
    })),
    photos: contentPort<Photo>(client, "photos", (row) => ({
      id: str(row, "id"),
      src: str(row, "src"),
      alt: str(row, "alt"),
      showOnHomepage: bool(row, "show_on_homepage"),
      position: num(row, "position"),
      published: bool(row, "published"),
    }), (row) => ({
      id: row.id,
      src: row.src,
      alt: row.alt,
      show_on_homepage: row.showOnHomepage,
      position: row.position,
      published: row.published,
    })),
    testimonials: contentPort<Testimonial>(client, "testimonials", (row) => ({
      id: str(row, "id"),
      quote: str(row, "quote"),
      name: str(row, "name"),
      role: str(row, "role"),
      avatarUrl: str(row, "avatar_url") || null,
      position: num(row, "position"),
      published: bool(row, "published"),
    }), (row) => ({
      id: row.id,
      quote: row.quote,
      name: row.name,
      role: row.role,
      avatar_url: row.avatarUrl,
      position: row.position,
      published: row.published,
    })),
    faqs: contentPort<Faq>(client, "faqs", (row) => ({
      id: str(row, "id"),
      question: str(row, "question"),
      answer: str(row, "answer"),
      position: num(row, "position"),
      published: bool(row, "published"),
    }), (row) => ({
      id: row.id,
      question: row.question,
      answer: row.answer,
      position: row.position,
      published: row.published,
    })),
    plans: plansPort(client),
    experience: contentPort<Experience>(client, "experience", (row) => ({
      id: str(row, "id"),
      role: str(row, "role"),
      company: str(row, "company"),
      period: str(row, "period"),
      position: num(row, "position"),
      published: bool(row, "published"),
    }), (row) => ({
      id: row.id,
      role: row.role,
      company: row.company,
      period: row.period,
      position: row.position,
      published: row.published,
    })),
    awards: contentPort(client, "awards", (row) => ({
      id: str(row, "id"),
      name: str(row, "name"),
      count: str(row, "count"),
      href: str(row, "href"),
      position: num(row, "position"),
      published: bool(row, "published"),
    }), (row) => ({
      id: row.id,
      name: row.name,
      count: row.count,
      href: row.href,
      position: row.position,
      published: row.published,
    })),
    stats: contentPort(client, "about_stats", (row) => ({
      id: str(row, "id"),
      value: str(row, "value"),
      label: str(row, "label"),
      position: num(row, "position"),
      published: bool(row, "published"),
    }), (row) => ({
      id: row.id,
      value: row.value,
      label: row.label,
      position: row.position,
      published: row.published,
    })),
    media: createSupabaseMedia(client, bucket),
    bookings: {
      async list() {
        const { data, error } = await client.from("bookings").select("*").order("created_at", { ascending: false })
        await throwIf(error)
        return asRows(data).map(bookingFrom)
      },
      async save(row: Booking) {
        const payload = {
          id: row.id,
          name: row.name,
          email: row.email,
          phone: row.phone,
          needs: row.needs,
          plan: row.plan,
          note: row.note,
          source: row.source,
          came_from: row.cameFrom,
          status: row.status,
          start_time: row.startTime,
          end_time: row.endTime,
          timezone: row.timezone,
          meet_url: row.meetUrl,
          created_at: row.createdAt,
          updated_at: Date.now(),
        }
        const { data, error } = await client.from("bookings").upsert(payload).select("*").single()
        await throwIf(error)
        return bookingFrom(asRow(data))
      },
      async remove(id: string) {
        await throwIf((await client.from("bookings").delete().eq("id", id)).error)
      },
      async removeMany(ids: readonly string[]) {
        await throwIf((await client.from("bookings").delete().in("id", [...ids])).error)
      },
    },
    /** Load feature lines and attach them to plans. `plans.list()` already does this. */
    hydratePlanFeatures(plans: Plan[]) {
      return loadPlanFeatures(client, plans)
    },
  }
}

-- Admin kit schema for Supabase (Postgres).
-- Apply in the host project. This file does not connect to a database.
--
-- Public visitors can read rows with published = true.
-- Writes require a row in public.admins for auth.uid().
-- Bookings are not public: the site inserts them with the service role.

create table if not exists public.admins (
  user_id uuid primary key references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.admins where user_id = auth.uid()
  );
$$;

revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to anon, authenticated;

create table if not exists public.categories (
  id text primary key,
  title text not null,
  slug text not null unique,
  position integer not null default 0,
  published boolean not null default false
);

create table if not exists public.projects (
  id text primary key,
  title text not null,
  slug text not null unique,
  category_id text references public.categories (id) on delete set null,
  summary text not null default '',
  client text not null default '',
  year text not null default '',
  live_url text not null default '',
  cover_url text,
  show_on_homepage boolean not null default false,
  published boolean not null default false,
  position integer not null default 0
);

create table if not exists public.settings (
  key text primary key,
  value text not null,
  updated_at timestamptz not null default now()
);

create table if not exists public.clients (
  id text primary key,
  name text not null,
  logo_url text,
  row_index integer not null default 0,
  position integer not null default 0,
  published boolean not null default false
);

create table if not exists public.photos (
  id text primary key,
  src text not null default '',
  alt text not null default '',
  show_on_homepage boolean not null default false,
  position integer not null default 0,
  published boolean not null default false
);

create table if not exists public.testimonials (
  id text primary key,
  quote text not null,
  name text not null,
  role text not null default '',
  avatar_url text,
  position integer not null default 0,
  published boolean not null default false
);

create table if not exists public.faqs (
  id text primary key,
  question text not null,
  answer text not null,
  position integer not null default 0,
  published boolean not null default false
);

create table if not exists public.plans (
  id text primary key,
  name text not null,
  blurb text not null default '',
  monthly_price integer,
  badge text not null default '',
  cta_label text not null default '',
  cta_href text not null default '',
  position integer not null default 0,
  published boolean not null default false
);

create table if not exists public.plan_features (
  id text primary key,
  plan_id text not null references public.plans (id) on delete cascade,
  text text not null,
  position integer not null default 0
);

create table if not exists public.about_stats (
  id text primary key,
  value text not null,
  label text not null,
  position integer not null default 0,
  published boolean not null default false
);

create table if not exists public.experience (
  id text primary key,
  role text not null,
  company text not null default '',
  period text not null default '',
  position integer not null default 0,
  published boolean not null default false
);

create table if not exists public.awards (
  id text primary key,
  name text not null,
  count text not null default '',
  href text not null default '',
  position integer not null default 0,
  published boolean not null default false
);

create table if not exists public.media (
  id text primary key,
  filename text not null,
  mime text not null,
  size integer not null default 0,
  url text not null default '',
  storage_path text not null default '',
  width integer,
  height integer,
  created_at timestamptz not null default now()
);

create table if not exists public.bookings (
  id text primary key,
  created_at bigint not null,
  updated_at bigint not null,
  status text not null default 'booked',
  name text not null default '',
  email text not null default '',
  phone text not null default '',
  needs text not null default '',
  plan text not null default '',
  note text not null default '',
  source text not null default 'site',
  came_from text not null default '',
  start_time bigint,
  end_time bigint,
  timezone text not null default '',
  meet_url text not null default ''
);

create index if not exists projects_position_idx on public.projects (position);
create index if not exists projects_homepage_idx on public.projects (show_on_homepage, position);
create index if not exists bookings_created_idx on public.bookings (created_at);

alter table public.admins enable row level security;
alter table public.categories enable row level security;
alter table public.projects enable row level security;
alter table public.settings enable row level security;
alter table public.clients enable row level security;
alter table public.photos enable row level security;
alter table public.testimonials enable row level security;
alter table public.faqs enable row level security;
alter table public.plans enable row level security;
alter table public.plan_features enable row level security;
alter table public.about_stats enable row level security;
alter table public.experience enable row level security;
alter table public.awards enable row level security;
alter table public.media enable row level security;
alter table public.bookings enable row level security;

-- A signed-in user can see their own admin row. Other reads and all writes
-- go through is_admin(), which is security definer so it does not recurse.
create policy admins_select_self on public.admins
  for select to authenticated
  using (user_id = auth.uid() or public.is_admin());

create policy admins_write on public.admins
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- Settings are site copy. The public site needs them; only admins write.
create policy settings_read on public.settings
  for select to anon, authenticated
  using (true);

create policy settings_write on public.settings
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- Media rows are addresses of public files. Only admins change them.
create policy media_read on public.media
  for select to anon, authenticated
  using (true);

create policy media_write on public.media
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- Bookings hold personal data. No anon read or write.
create policy bookings_admin on public.bookings
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- Published content is public. Admins can read drafts and write.
do $$
declare
  t text;
begin
  foreach t in array array[
    'categories', 'projects', 'clients', 'photos', 'testimonials', 'faqs',
    'plans', 'about_stats', 'experience', 'awards'
  ]
  loop
    execute format(
      'create policy %I on public.%I for select to anon, authenticated using (published = true or public.is_admin())',
      t || '_read', t
    );
    execute format(
      'create policy %I on public.%I for all to authenticated using (public.is_admin()) with check (public.is_admin())',
      t || '_write', t
    );
  end loop;
end $$;

-- Features follow their plan: public when the plan is published.
create policy plan_features_read on public.plan_features
  for select to anon, authenticated
  using (
    public.is_admin()
    or exists (
      select 1 from public.plans p
      where p.id = plan_id and p.published = true
    )
  );

create policy plan_features_write on public.plan_features
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());

insert into storage.buckets (id, name, public)
values ('media', 'media', true)
on conflict (id) do nothing;

create policy media_bucket_read on storage.objects
  for select to anon, authenticated
  using (bucket_id = 'media');

create policy media_bucket_write on storage.objects
  for all to authenticated
  using (bucket_id = 'media' and public.is_admin())
  with check (bucket_id = 'media' and public.is_admin());

# Admin kit on Supabase

The UI pieces do not import Supabase. The host creates the client and passes it to `createSupabaseAdmin`.

## Install

```bash
npm install @supabase/supabase-js
npx shadcn@latest add @retana/admin-kit
```

Answer **no** if the CLI asks to overwrite primitives the host already has (`button`, `sidebar`, `dialog`, and the rest).

Apply `001_admin_content.sql` in the Supabase SQL editor. It creates the content tables, RLS, and a public `media` storage bucket.

Add yourself:

```sql
insert into public.admins (user_id) values ('<auth.users id>');
```

## Next.js

```tsx
// lib/supabase/client.ts
import { createClient } from "@supabase/supabase-js"
import { createSupabaseAdmin } from "@/lib/supabase-admin"

export function adminPorts() {
  const client = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
  )
  return createSupabaseAdmin(client)
}
```

Guard the route in a server layout. The registry pieces do not import `next`.

```tsx
// app/admin/layout.tsx
import { redirect } from "next/navigation"
import { createClient } from "@/lib/supabase/server"

export default async function AdminLayout({ children }: { children: React.ReactNode }) {
  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) redirect("/login")
  const { data: admin } = await supabase.from("admins").select("user_id").eq("user_id", user.id).maybeSingle()
  if (!admin) redirect("/")
  return children
}
```

Wire a screen with the same callbacks the demo uses:

```tsx
const ports = adminPorts()
const projects = await ports.projects.list()

<SortableBoard
  items={projects}
  categories={categories}
  onReorder={(ids) => ports.projects.reorder(ids)}
  onToggleHomepage={async (id, show) => {
    const row = projects.find((item) => item.id === id)
    if (row) await ports.projects.save({ ...row, showOnHomepage: show })
  }}
/>
```

## Vite + React 18

Same client, no server layout. Guard in the router:

```tsx
const { data: { session } } = await supabase.auth.getSession()
if (!session) return <Navigate to="/login" replace />
const { data: admin } = await supabase.from("admins").select("user_id").eq("user_id", session.user.id).maybeSingle()
if (!admin) return <Navigate to="/" replace />
```

Pass `themeController` from your theme hook if you have one. Otherwise the shell toggles the `dark` class itself.

## What the policies do

- `published = true` rows are readable without a session.
- `settings` and `media` are readable by the public site. Only admins write.
- `bookings` are invisible to anon. Insert them from a server action with the service role.
- Storage object writes on the `media` bucket require `is_admin()`.

